 * gap that docblock does not cover: `window.getComputedStyle()` in this project's installed jsdom
 * does not dynamically re-resolve a pseudo-class-gated rule after the DOM's focus state changes
 * post-mount, even for a bare self-referential `&:has(:focus-visible)` rule with no descendant
 * selector at all (confirmed by direct experiment — a real `.focus()` call correctly updates
 * `document.activeElement` and correctly makes `element.matches(':has(:focus-visible)')` return
 * `true`, but a subsequent `getComputedStyle()` read still reports the PRE-focus value). This is
 * exactly why Fix 1's proof above (a purely static cascade with no pseudo-class involved) could
 * safely use `getComputedStyle()` while this one cannot. `.matches()` against the exact literal
 * descendant-selector suffix the real recipe emits (`SIZE_CHIPS_KEY`, module-scope above) — with
 * only the Emotion-specific `&` swapped for a plain stand-in ancestor selector, since `&` is an
 * Emotion/PostCSS nesting token resolved at CSS-in-JS compile time, not a selector nwsapi
 * understands directly — correctly reflects the live DOM focus state both before and after a
 * real `.focus()` call, so it is what actually proves the mechanism here.
 *
 * jsdom has no concept of "focus triggered by a mouse click" vs "focus triggered by keyboard" —
 * there is no such distinction to probe — so this test proves the reveal still fires on real
 * focus, exactly as it did for `:focus-within`; it cannot prove, and only a real browser can,
 * that a mouse-click-focused button is excluded, which is the actual bug this fix (Fix H)
 * addresses.
 */
describe('ZimmProductCard — Fix 2 (Scorer rework round 1): size chips reveal on keyboard focus, not just mouse hover', () => {
  test('an ancestor :has(:focus-visible) + the real recipe’s own descendant-selector suffix flips from non-matching to matching once a nested control receives real focus', async () => {
    const user = userEvent.setup();
    const ANCESTOR_STAND_IN = '[data-testid="card-root"]';
    // Swap the Emotion-only `&` token for the stand-in ancestor selector above — the remaining,
    // actual descendant path comes straight from the real recipe's own module-scope constant,
    // not a hand-typed second copy.
    const revealSelector = FOCUS_VISIBLE_SIZE_CHIPS_KEY.replace('&', ANCESTOR_STAND_IN);

    const { container } = render(
      <div data-testid="card-root">
        <div data-card-slot="content">
          <button type="button">Add to bag</button>
          <div data-card-slot="sizeChips">size chips</div>
        </div>
      </div>,
    );

    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
    // Before focus lands anywhere in the card, the reveal selector does not match — mirrors the
    // unconditional (outside-media-query) hidden default a touch/no-hover pointer sees permanently
    // in the real recipe (Fix J, SFCC-236: `position: 'absolute', clipPath: 'inset(50%)'` — was
    // `display: 'none'`; this test's own assertion is unaffected either way, since `.matches()`
    // only checks the selector, not which property the matched rule sets).
    expect(sizeChips.matches(revealSelector)).toBe(false);

    // Fix H rework: `await user.tab()` (a real simulated Tab keypress), not a bare `.focus()` call
    // (what this test used for the `:focus-within` version, and what a first pass at this rename
    // kept unchanged). Empirically, in THIS project's installed jsdom/nwsapi, a bare `.focus()`
    // call satisfies `:focus-visible` only when nothing else in the same test FILE has already
    // driven a real pointer-originated focus via `userEvent.click()` — Vitest's jsdom environment
    // is created once per file, not per test, so state can carry over. Confirmed by direct
    // experiment: this exact assertion passes when this test runs alone, and fails when it runs
    // after any of this file's own `user.click(...)` tests (e.g. the "bag button" test in the
    // click-wiring describe block above) — with `document.hasFocus()`/`document.activeElement`
    // still correctly pointing at this test's own button, but `button.matches(':focus-visible')`
    // alone (no `:has()`, no compound selector) already false. `:focus`/`:focus-within` are
    // unaffected either way. `await user.tab()` sidesteps this reliably (verified against both the
    // isolated case and the full 57-test file) and is arguably the more faithful simulation of
    // what this test claims to prove in the first place — a keyboard user tabbing into the card —
    // than an imperative `.focus()` call, which does not represent any particular input modality.
    await user.tab();

    // :has(:focus-visible) on the card ROOT (not on the size-chip wrapper itself, which would be
    // circular — an element hidden via clip-path is still focusable/in the tab order, but an
    // element hidden the OLD `display: 'none'` way was neither) bubbles from this descendant's
    // real focus state up to the root, so the reveal selector now matches — the same live-DOM
    // condition the real recipe's CSS rule keys its reveal off (Fix J: `position: 'static',
    // clipPath: 'none'` — was `display: 'block'`).
    expect(sizeChips.matches(revealSelector)).toBe(true);
  });

  test('the reveal selector still does not match a sibling control receiving focus outside the card root entirely', async () => {
    const user = userEvent.setup();
    const ANCESTOR_STAND_IN = '[data-testid="card-root"]';
    const revealSelector = FOCUS_VISIBLE_SIZE_CHIPS_KEY.replace('&', ANCESTOR_STAND_IN);

    const { container } = render(
      <>
        <button type="button">Outside the card</button>
        <div data-testid="card-root">
          <div data-card-slot="content">
            <div data-card-slot="sizeChips">size chips</div>
          </div>
        </div>
      </>,
    );

    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
    // Keyboard-originated focus via user.tab(), not a bare .focus() call — see the sibling test
    // above (lines ~923-937) for the full jsdom/nwsapi quirk this sidesteps: a bare .focus() call
    // only satisfies :focus-visible when nothing earlier in this test file has already driven a
    // real userEvent.click()-originated focus, which this file's own earlier describe blocks do.
    // Without this, the assertion below could pass vacuously — false because nothing has
    // :focus-visible at all by this point in the run, not because the selector genuinely excludes
    // focus outside the card root. The intermediate assertion confirms focus actually landed on
    // this element before the real thing under test is checked.
    await user.tab();
    expect(screen.getByRole('button', { name: 'Outside the card' })).toHaveFocus();

    // Guards against a selector so loose it would match regardless of where focus actually is —
    // focus outside the card root must never trigger the reveal.
    expect(sizeChips.matches(revealSelector)).toBe(false);
  });
});

