  /**
   * FLAGGED FOR RATIFICATION (discovered running this test, not anticipated by the build step's
   * own instructions — see this session's report): the anchor's accessible name is NOT purely the
   * `VisuallyHidden` product name. Per standard name-from-content computation, a descendant
   * `<img>`'s own `alt` text is concatenated onto its containing link's accessible name — so the
   * real computed name here is "Natura Dress Zimmermann dress, front" (product name + a space +
   * `PRIMARY.alt`), not "Natura Dress" alone. `primaryImage`/`hoverImage` are passed through
   * unmodified into `ZimmProductCardMedia` per this build step's own explicit instruction, so nothing
   * here suppresses the image's own `alt` — an anchored-at-start match (product name is the
   * FIRST/leading contributor, confirmed via DOM order) is what this test can honestly assert,
   * not an exact-string match against the product name alone.
   */
  test('renders exactly one real, keyboard-reachable link, whose accessible name leads with the product name', () => {
    wrap(<ZimmProductCard {...buildCardProps('recentlyViewed')} />);
    const links = screen.getAllByRole('link');
    expect(links).toHaveLength(1);
    expect(screen.getByRole('link', { name: /^Natura Dress\b/ })).toHaveAttribute('href', '/product/1');
  });
});

